<script setup lang="ts">
import CategoryFilter from '../components/CategoryFilter.vue';import CategoryAssignment from '../components/CategoryAssignment.vue';
import {useRoute} from 'vue-router';
import LibraryTargetPicker from '../components/LibraryTargetPicker.vue';import LibraryArchiveDialog from '../components/LibraryArchiveDialog.vue';import ScanReport from '../components/ScanReport.vue';import {readableLibraries,booksOfKind,type LibraryRef} from '../api/libraries';
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue';import {api,state,refreshAccess} from '../state';import type {Book} from '../api/client';import BookCover from '../components/BookCover.vue';import DirectoryPicker from '../components/DirectoryPicker.vue';
const route=useRoute(),targetLibrary=ref(0),archiveLibrary=ref<LibraryRef|null>(null);const libraries=ref<LibraryRef[]>([]),selected=ref(typeof route.query.library==='string'?route.query.library:''),books=ref<Book[]>([]),total=ref(0),page=ref(1),q=ref(''),sort=ref('recent'),loading=ref(true),error=ref(''),message=ref('');const selectedLibrary=computed(()=>libraries.value.find(lib=>String(lib.id)===selected.value));const admin=computed(()=>state.user?.role==='admin'),createOpen=ref(false),folderOpen=ref(false),name=ref(''),path=ref(''),creating=ref(false),uploading=ref(false),percent=ref(0),fileInput=ref<HTMLInputElement>(),job=ref<any>();const category=ref(typeof route.query.category==='string'?route.query.category:''),detail=ref<Book|null>(null);let detailGeneration=0;let generation=0,closed=false,timer:ReturnType<typeof setTimeout>|undefined,uploadAbort=new AbortController(),uploadID='';let jobEpoch=0;
async function load(){const g=++generation;loading.value=true;error.value='';try{const params=new URLSearchParams({content_kind:'comic',page:String(page.value),q:q.value,sort:sort.value});if(selected.value)params.set('library',selected.value);if(category.value)params.set('category',category.value);const data=await api.get<any>('/books?'+params);if(g!==generation||closed)return;books.value=booksOfKind(data.items as Book[],'comic').filter(book=>!state.revokedBookIDs.includes(book.id));total.value=data.total}catch(e:any){if(g===generation)error.value=e.message}finally{if(g===generation)loading.value=false}}
async function init(){try{libraries.value=(await api.get<any>('/libraries')).items;libraries.value=readableLibraries(libraries.value,'comic');if(selected.value&&!libraries.value.some(lib=>String(lib.id)===selected.value))selected.value=''}catch(e:any){error.value=e.message}await load()}
function choose(id:string){selected.value=id;page.value=1;void load()}
watch(selected,()=>{category.value='';page.value=1},{flush:'sync'});watch(category,()=>{page.value=1;void load()});
async function openDetail(book:Book){const g=++detailGeneration;detail.value={...book,can_manage:false};try{const row=await api.get<Book>('/books/'+book.id);if(!closed&&g===detailGeneration)detail.value=row}catch(e:any){if(!closed&&g===detailGeneration)message.value=e.message}}
function closeDetail(){detailGeneration++;detail.value=null}
function escape(e:KeyboardEvent){if(e.key==='Escape')closeDetail()}
async function track(id:number,epoch=++jobEpoch){try{const current=await api.get<any>('/imports/'+id);if(closed||epoch!==jobEpoch)return;job.value=current;if(current.status==='pending'||current.status==='running'){timer=setTimeout(()=>void track(id,epoch),1000);return}message.value=current.status==='completed'?(current.scan_report?.imported===0?'扫描结束，详见格式报告':'导入完成'):current.status==='cancelled'?'已取消':'导入失败：'+current.error;await load()}catch(e:any){if(!closed)error.value=e.message}}
async function create(){if(!path.value||creating.value)return;creating.value=true;error.value='';try{const lib=await api.post<any>('/libraries',{name:name.value.trim(),path:path.value,poll_seconds:0,content_kind:'comic',storage_kind:'directory',visibility:'shared'});createOpen.value=false;libraries.value.push(lib);selected.value=String(lib.id);const task=await api.post<any>('/libraries/'+lib.id+'/scan');void track(task.id);await load()}catch(e:any){error.value=e.message}finally{creating.value=false}}
async function scan(){if(!selectedLibrary.value?.can_manage||selectedLibrary.value.storage_kind!=='directory')return;try{const task=await api.post<any>('/libraries/'+selected.value+'/scan');void track(task.id)}catch(e:any){error.value=e.message}}
async function cancel(){if(uploading.value&&uploadID){uploadAbort.abort();try{await api.delete('/uploads/'+uploadID);message.value='已取消上传'}catch(e:any){error.value=e.message};return}if(!job.value)return;try{await api.post('/imports/'+job.value.id+'/cancel');void track(job.value.id)}catch(e:any){error.value=e.message}}
async function upload(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file||!targetLibrary.value)return;uploadAbort=new AbortController();uploading.value=true;percent.value=0;error.value='';try{const upload=await api.post<any>('/uploads/init',{name:file.name,size:file.size,content_kind:'comic',library_id:targetLibrary.value});uploadID=upload.id;if(closed||uploadAbort.signal.aborted){await api.delete('/uploads/'+uploadID);return}for(let n=0;n<upload.parts;n++){await api.request(`/uploads/${upload.id}/part?index=${n}`,{method:'PUT',headers:{'Content-Type':'application/octet-stream'},signal:uploadAbort.signal,body:file.slice(n*upload.part_size,Math.min(file.size,(n+1)*upload.part_size))});if(closed)return;percent.value=Math.round((n+1)/upload.parts*100)}const task=await api.post<any>('/uploads/'+upload.id+'/complete');choose('');void track(task.id)}catch(e:any){if(e.name!=='AbortError')error.value=e.message}finally{uploading.value=false;uploadID='';(e.target as HTMLInputElement).value=''}}
watch(()=>state.accessEpoch,()=>{if(detail.value&&state.revokedBookIDs.includes(detail.value.id))closeDetail();if(state.revokedBookIDs.some(id=>books.value.some(book=>book.id===id)))books.value=books.value.filter(book=>!state.revokedBookIDs.includes(book.id));void init()});
function comicFocus(){if(document.visibilityState==='visible'&&!state.offline){if(detail.value)void openDetail(detail.value);void refreshAccess(books.value.map(book=>book.id)).catch(()=>{});void init()}}
onMounted(()=>{void init();window.addEventListener('focus',comicFocus);window.addEventListener('online',comicFocus);window.addEventListener('keydown',escape)});onBeforeUnmount(()=>{window.removeEventListener('focus',comicFocus);window.removeEventListener('online',comicFocus);window.removeEventListener('keydown',escape);closed=true;detailGeneration++;generation++;jobEpoch++;uploadAbort.abort();if(uploadID)void api.delete('/uploads/'+uploadID).catch(()=>{});clearTimeout(timer)});
</script>
<template><main class="comic-library page"><aside class="comic-sidebar"><h2><span aria-hidden="true">▤</span> 漫画库</h2><button :class="{active:!selected}" @click="choose('')">全部漫画</button><button v-for="lib in libraries" :key="lib.id" :class="{active:selected===String(lib.id)}" @click="choose(String(lib.id))" :title="lib.name">{{lib.name}}</button><button v-if="admin" class="new-library" @click="name='';path='';createOpen=true">＋ 新建漫画库</button></aside><section class="comic-content"><div class="page-title"><div><h1>我的漫画</h1><p>{{total}} 册 · 你的故事收藏</p></div><div class="comic-actions"><RouterLink class="button" :to="{path:'/categories',query:{content_kind:'comic',...(selected?{library:selected}:{})}}">分类</RouterLink><RouterLink class="button" :to="{path:'/collections',query:{content_kind:'comic',...(selected?{library:selected}:{})}}">系列集合</RouterLink><button v-if="admin&&books.length" class="mobile-create" @click="name='';path='';createOpen=true">新建漫画库</button><button v-if="selectedLibrary?.can_manage&&selectedLibrary?.storage_kind==='directory'" @click="scan">重新扫描</button><button class="primary" :disabled="uploading||!targetLibrary" @click="fileInput?.click()">{{uploading?`正在上传 ${percent}%`:'导入漫画'}}</button><button v-if="uploading" @click="cancel">取消上传</button><input ref="fileInput" hidden type="file" accept=".cbz,.pdf,.epub,.mobi" aria-label="导入漫画文件" @change="upload"></div></div><LibraryTargetPicker v-model="targetLibrary" kind="comic" :disabled="uploading"/><div v-if="selectedLibrary?.can_manage" class="row-actions"><RouterLink class="button" to="/admin/libraries">管理与授权</RouterLink><button @click="archiveLibrary=selectedLibrary">删除整个漫画库</button></div><label class="mobile-library">漫画库<select :value="selected" @change="choose(($event.target as HTMLSelectElement).value)"><option value="">全部漫画</option><option v-for="lib in libraries" :key="lib.id" :value="String(lib.id)">{{lib.name}}</option></select></label><form class="toolbar" @submit.prevent="page=1;load()"><input v-model="q" aria-label="搜索漫画" placeholder="搜索漫画名或作者"><button>搜索</button><select v-model="sort" aria-label="漫画排序" @change="page=1;load()"><option value="recent">最近添加</option><option value="title">名称</option></select><CategoryFilter v-model="category" :library="selected" kind="comic" :libraries="libraries" label="漫画分类筛选"/></form><p v-if="error" role="alert" class="error">{{error}} <button @click="init">重试</button></p><p v-if="message" role="status">{{message}}</p><ScanReport v-if="job?.scan_report" :report="job.scan_report"/><div v-if="job?.status==='pending'||job?.status==='running'" class="scan-state" role="status"><span>{{job.status==='pending'?'等待导入':'正在导入'}} · 已处理 {{job.processed}} 册</span><button @click="cancel">取消</button></div><p v-if="loading" role="status">正在打开漫画库…</p><div v-else-if="books.length" class="comic-grid"><article v-for="book in books" :key="book.id"><RouterLink :to="'/read/'+book.id"><BookCover :book="book"/><h3>{{book.title}}</h3></RouterLink><p>{{book.series_name||book.author||'漫画'}}<span v-if="book.volume_label"> · {{book.volume_label}}</span></p><small>{{book.format.toUpperCase()}}<template v-if="book.page_count"> · {{book.page_count}} 页</template></small><button class="text-button" @click="openDetail(book)">详情</button></article></div><section v-else class="comic-empty"><img class="empty-symbol" src="/brand-icon.svg" alt="" width="92" height="92"><h2>{{q?'没有找到这部漫画':libraries.length?'漫画库还没有内容':'开始你的漫画收藏'}}</h2><p>{{q?'换一个名称试试。':admin?'选择 NAS 上的漫画目录，或导入 CBZ、PDF、EPUB、MOBI 开始阅读。':'导入 CBZ、PDF、EPUB 或 MOBI 到个人漫画库，再按需授权共享。'}}</p><button v-if="admin&&!q" class="primary" @click="createOpen=true">新建漫画库</button></section><div v-if="total>40" class="pagination"><button :disabled="page===1" @click="page--;load()">上一页</button><span>{{page}} / {{Math.ceil(total/40)}}</span><button :disabled="page*40>=total" @click="page++;load()">下一页</button></div></section></main><div v-if="detail" class="modal-backdrop" @click.self="closeDetail"><section class="sheet comic-detail" role="dialog" aria-modal="true" aria-label="漫画详情"><button class="close" @click="closeDetail">关闭</button><h2>{{detail.title}}</h2><p>{{detail.author||'佚名'}} · {{detail.format.toUpperCase()}}</p><p>{{detail.description||'暂无简介'}}</p><RouterLink class="button primary" :to="'/read/'+detail.id">开始阅读</RouterLink><CategoryAssignment :key="detail.id" :book="detail"/></section></div><div v-if="createOpen" class="modal-backdrop" @click.self="createOpen=false"><section class="sheet create-comic" role="dialog" aria-modal="true" aria-label="新建漫画库"><button class="close" @click="createOpen=false">关闭</button><h2>新建漫画库</h2><form @submit.prevent="create"><label>漫画库名称<input v-model="name" maxlength="40" placeholder="例如：我的漫画" required></label><label>漫画库目录<button type="button" aria-label="选择漫画目录" class="folder-select" @click="folderOpen=true"><span>{{path||'选择漫画目录'}}</span><span aria-hidden="true">▱</span></button></label><p>此目录中的 CBZ、PDF、EPUB 和 MOBI 会递归发现，并报告导入和跳过的格式。</p><p v-if="error" role="alert" class="error">{{error}}</p><div class="create-actions"><button type="button" @click="createOpen=false">取消</button><button class="primary" :disabled="!path||!name.trim()||creating">{{creating?'正在创建…':'创建并导入'}}</button></div></form></section></div><LibraryArchiveDialog v-if="archiveLibrary" :library="archiveLibrary" @close="archiveLibrary=null" @archived="selected='';message='漫画库已归档，可在书库管理中恢复';init()"/><DirectoryPicker v-if="folderOpen" @close="folderOpen=false" @select="path=$event;folderOpen=false"/></template>
<style scoped>
.comic-detail{width:min(620px,calc(100% - 32px));max-height:calc(100dvh - 32px);overflow:auto;padding:28px}.comic-actions{flex-wrap:wrap}.comic-library{display:flex;padding:0;min-height:calc(100dvh - 120px);max-width:1320px;gap:0;border:1px solid var(--border);border-radius:18px;overflow:hidden;margin-top:24px;background:var(--surface)}.comic-sidebar{width:220px;flex:none;padding:24px 16px;background:#f2f5f3;border-right:1px solid var(--border)}.comic-sidebar h2{font-size:17px;padding:0 12px;margin:0 0 24px}.comic-sidebar>button{width:100%;border:0;text-align:left;padding:12px;min-height:44px;margin:4px 0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;background:transparent;color:var(--muted)}.comic-sidebar>button.active{background:#e4eeea;color:var(--accent);font-weight:650}.comic-sidebar>button.new-library{margin-top:24px;color:var(--accent)}.comic-content{padding:28px;min-width:0;flex:1}.comic-content h1{font-size:26px}.mobile-create{display:none}.comic-actions{display:flex;gap:8px}.comic-content .toolbar{margin-bottom:24px}.comic-content .toolbar>input{min-width:0}.comic-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(138px,1fr));gap:24px 20px}.comic-grid article{min-width:0;max-width:190px}.comic-grid h3{font-size:15px;line-height:1.5;margin:10px 0 4px}.comic-grid p,.comic-grid small{font-size:12px;color:var(--muted);margin:4px 0}.comic-empty{text-align:center;padding:90px 12px}.comic-empty h2{font-size:20px}.empty-symbol{opacity:.85;color:var(--accent);line-height:1.1}.comic-empty p{color:var(--muted);font-size:14px}.comic-empty button{margin-top:16px}.mobile-library{display:none}.scan-state{display:flex;align-items:center;justify-content:space-between;padding:12px;border-radius:12px;background:#e4eeea;margin:16px 0}.create-comic{max-width:620px;width:calc(100% - 32px);padding:28px}.create-comic label{margin-top:20px}.create-comic input{height:44px}.folder-select{width:100%;display:flex;align-items:center;justify-content:space-between;min-height:44px;gap:10px;text-align:left;margin:8px 0 0}.folder-select span:first-child{overflow-wrap:anywhere}.create-comic p{font-size:13px;color:var(--muted)}.create-actions{display:flex;justify-content:flex-end;gap:10px;border-top:1px solid var(--border);padding-top:20px;margin-top:24px}.create-actions button{margin:0}@media(max-width:750px){.mobile-create{display:inline-flex}.comic-actions{flex-wrap:wrap;justify-content:flex-end;max-width:200px}.comic-actions input[hidden]{display:none}.comic-library{display:block;border:0;border-radius:0;margin:0}.comic-sidebar{display:none}.comic-content{padding:22px 16px 100px}.comic-content h1{font-size:24px}.comic-content .page-title{gap:10px}.comic-actions button{padding:10px;font-size:13px}.mobile-library{display:block;margin-bottom:14px}.comic-content .toolbar{flex-wrap:wrap}.comic-content .toolbar>input{flex:1 1 180px}.comic-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:22px 18px}.comic-empty{padding:64px 10px}}
</style>
